-- ==========================================================================
-- CAREERMARG (DISHA V2) - SUPABASE POSTGRESQL PRODUCTION SCHEMA & DATA
-- Conforms to 3-Stage Assessment Framework (Group I, II, III)
-- ==========================================================================

-- 1. Enable UUID extension
CREATE EXTENSION IF NOT EXISTS "uuid-ossp";

-- 2. Assessment Questions Table
CREATE TABLE IF NOT EXISTS public.assessment_questions (
    id VARCHAR(64) PRIMARY KEY,
    tier VARCHAR(64) NOT NULL,
    submodule VARCHAR(64) NOT NULL,
    submodule_title VARCHAR(255),
    submodule_title_hi VARCHAR(255),
    trait_code VARCHAR(64) NOT NULL,
    trait_title VARCHAR(255),
    trait_title_hi VARCHAR(255),
    question_text TEXT NOT NULL,
    question_text_hi TEXT NOT NULL,
    type VARCHAR(32) DEFAULT 'likert_5',
    options JSONB NOT NULL DEFAULT '[]'::jsonb,
    correct_key VARCHAR(64),
    display_order INT DEFAULT 0,
    created_at TIMESTAMPTZ DEFAULT NOW()
);

-- 3. Student Assessment Profiles & Reports Table
CREATE TABLE IF NOT EXISTS public.student_profiles (
    id VARCHAR(128) PRIMARY KEY,
    email VARCHAR(255),
    name VARCHAR(255),
    grade VARCHAR(32),
    school VARCHAR(255),
    stream VARCHAR(64),
    city VARCHAR(128),
    role_model_archetype VARCHAR(64),
    aspiration TEXT,
    interest_tags JSONB DEFAULT '[]'::jsonb,
    saved_careers JSONB DEFAULT '[]'::jsonb,
    completed_tiers JSONB DEFAULT '[]'::jsonb,
    tier_answers JSONB DEFAULT '{}'::jsonb,
    trait_scores JSONB DEFAULT '{}'::jsonb,
    career_matches JSONB DEFAULT '[]'::jsonb,
    report JSONB DEFAULT '{}'::jsonb,
    created_at TIMESTAMPTZ DEFAULT NOW(),
    updated_at TIMESTAMPTZ DEFAULT NOW()
);

-- 4. Insert / Upsert 126 Assessment Questions
